const Checkpoint = ({ message, threadId, messageIdx, isCheckpointGhost, threadIsRunning }: { message: CheckpointEntry, threadId: string; messageIdx: number, isCheckpointGhost: boolean, threadIsRunning: boolean }) => {
	const accessor = useAccessor()
	const chatThreadService = accessor.get('IChatThreadService')
	const streamState = useFullChatThreadsStreamState()

	const isRunning = useChatThreadsStreamState(threadId)?.isRunning
	const isDisabled = useMemo(() => {
		if (isRunning) return true
		return !!Object.keys(streamState).find((threadId2) => streamState[threadId2]?.isRunning)
	}, [isRunning, streamState])

	return <div
		className={`flex items-center justify-center px-2 `}
	>
		<div
			className={`
                    text-xs
                    text-void-fg-3
                    select-none
                    ${isCheckpointGhost ? 'opacity-50' : 'opacity-100'}
					${isDisabled ? 'cursor-default' : 'cursor-pointer'}
                `}
			style={{ position: 'relative', display: 'inline-block' }} // allow absolute icon
			onClick={() => {
				if (threadIsRunning) return
				if (isDisabled) return
				chatThreadService.jumpToCheckpointBeforeMessageIdx({
					threadId,
					messageIdx,
					jumpToUserModified: messageIdx === (chatThreadService.state.allThreads[threadId]?.messages.length ?? 0) - 1
				})
			}}
			{...isDisabled ? {
				'data-tooltip-id': 'void-tooltip',
				'data-tooltip-content': `Disabled ${isRunning ? 'when running' : 'because another thread is running'}`,
				'data-tooltip-place': 'top',
			} : {}}
		>
			Checkpoint
		</div>
	</div>
}


type ChatBubbleMode = 'display' | 'edit'
type ChatBubbleProps = {
	chatMessage: ChatMessage,
	messageIdx: number,
	isCommitted: boolean,
	chatIsRunning: IsRunningType,
	threadId: string,
	currCheckpointIdx: number | undefined,
	_scrollToBottom: (() => void) | null,
}

const ChatBubble = (props: ChatBubbleProps) => {
	return <ErrorBoundary>
		<_ChatBubble {...props} />
	</ErrorBoundary>
}

const _ChatBubble = ({ threadId, chatMessage, currCheckpointIdx, isCommitted, messageIdx, chatIsRunning, _scrollToBottom }: ChatBubbleProps) => {
	const role = chatMessage.role

	const isCheckpointGhost = messageIdx > (currCheckpointIdx ?? Infinity) && !chatIsRunning // whether to show as gray (if chat is running, for good measure just dont show any ghosts)

	if (role === 'user') {
		return <UserMessageComponent
			chatMessage={chatMessage}
			isCheckpointGhost={isCheckpointGhost}
			currCheckpointIdx={currCheckpointIdx}
			messageIdx={messageIdx}
			_scrollToBottom={_scrollToBottom}
		/>
	}
	else if (role === 'assistant') {
		return <AssistantMessageComponent
			chatMessage={chatMessage}
			isCheckpointGhost={isCheckpointGhost}
			messageIdx={messageIdx}
			isCommitted={isCommitted}
		/>
	}
	else if (role === 'tool') {

		if (chatMessage.type === 'invalid_params') {
			return <div className={`${isCheckpointGhost ? 'opacity-50' : ''}`}>
				<InvalidTool toolName={chatMessage.name} message={chatMessage.content} mcpServerName={chatMessage.mcpServerName} />
			</div>
		}

		const toolName = chatMessage.name
		const isBuiltInTool = isABuiltinToolName(toolName)
		const ToolResultWrapper = isBuiltInTool ? builtinToolNameToComponent[toolName]?.resultWrapper as ResultWrapper<ToolName>
			: MCPToolWrapper as ResultWrapper<ToolName>

		if (ToolResultWrapper)
			return <>
				<div className={`${isCheckpointGhost ? 'opacity-50' : ''}`}>
					<ToolResultWrapper
						toolMessage={chatMessage}
						messageIdx={messageIdx}
						threadId={threadId}
					/>
				</div>
				{chatMessage.type === 'tool_request' ?
					<div className={`${isCheckpointGhost ? 'opacity-50 pointer-events-none' : ''}`}>
						<ToolRequestAcceptRejectButtons toolName={chatMessage.name} />
					</div> : null}
			</>
		return null
	}

	else if (role === 'interrupted_streaming_tool') {
		return <div className={`${isCheckpointGhost ? 'opacity-50' : ''}`}>
			<CanceledTool toolName={chatMessage.name} mcpServerName={chatMessage.mcpServerName} />
		</div>
	}

	else if (role === 'checkpoint') {
		return <Checkpoint
			threadId={threadId}
			message={chatMessage}
			messageIdx={messageIdx}
			isCheckpointGhost={isCheckpointGhost}
			threadIsRunning={!!chatIsRunning}
		/>
	}

	else if (role === 'flow_review') {
		return <FlowReviewComponent
			chatMessage={chatMessage}
			isCheckpointGhost={isCheckpointGhost}
		/>
	}

}

const FlowReviewComponent = ({ chatMessage, isCheckpointGhost }: {
	chatMessage: ChatMessage & { role: 'flow_review' },
	isCheckpointGhost: boolean,
}) => {
	const accessor = useAccessor()
	const chatThreadsService = accessor.get('IChatThreadService')
	const [isExpanded, setIsExpanded] = useState(true)

	const onApprove = useCallback(() => {
		try {
			const threadId = chatThreadsService.state.currentThreadId
			chatThreadsService.approveFlowReview(threadId)
		} catch (e) { console.error('Error approving flow review:', e) }
	}, [chatThreadsService])

	const onReject = useCallback(() => {
		try {
			const threadId = chatThreadsService.state.currentThreadId
			chatThreadsService.rejectFlowReview(threadId)
		} catch (e) { console.error('Error rejecting flow review:', e) }
	}, [chatThreadsService])

	const { status } = chatMessage

	// Flow phases for the progress stepper
	const flowPhases = [
		{ key: 'design', label: 'Design', icon: '🎨', file: 'DESIGN.md' },
		{ key: 'search', label: 'Search', icon: '🔍', file: 'SEARCH.md' },
		{ key: 'research', label: 'Search', icon: '🔍', file: 'SEARCH.md' },
		{ key: 'writing', label: 'Writing', icon: '✍️', file: 'WRITING.md' },
		{ key: 'planning', label: 'Planning', icon: '📋', file: 'PLANNING.md' },
		{ key: 'coding', label: 'Coding', icon: '💻', file: '' },
		{ key: 'coder', label: 'Coding', icon: '💻', file: '' },
	]

	// Determine which phases exist in this session and mark their status
	const currentFlowKey = chatMessage.flowRole.toLowerCase()
	const currentIdx = chatMessage.completedTaskIndex
	const totalTasks = chatMessage.totalTasks

	// Build a simplified stepper: show the current task and its neighbors
	const allPhaseKeys = ['design', 'search', 'writing', 'planning', 'coding']
	const currentPhase = flowPhases.find(p => p.key === currentFlowKey)

	// Container styles based on status
	const containerStyles = {
		pending: 'border border-[var(--vscode-focusBorder)] bg-[var(--vscode-editor-background)]',
		approved: 'border border-green-500/40 bg-green-500/5',
		rejected: 'border border-red-500/40 bg-red-500/5 opacity-70',
	}

	return (
		<div className={`${isCheckpointGhost ? 'opacity-50 pointer-events-none' : ''} my-3`}>
			<div className={`rounded-lg overflow-hidden ${containerStyles[status]}`}>

				{/* ===== Header ===== */}
				<div className="px-4 pt-3 pb-2">
					<div className="flex items-center justify-between">
						<div className="flex items-center gap-2">
							<span className="text-base">📝</span>
							<span className="font-semibold text-sm text-[var(--vscode-foreground)]">
								ドキュメントレビュー
							</span>
						</div>
						{/* Status badge */}
						{status === 'pending' ? (
							<span className="text-[10px] px-2 py-0.5 rounded-full font-medium bg-[var(--vscode-focusBorder)]/20 text-[var(--vscode-focusBorder)] border border-[var(--vscode-focusBorder)]/40">
								レビュー待ち
							</span>
						) : status === 'approved' ? (
							<span className="text-[10px] px-2 py-0.5 rounded-full font-medium bg-green-500/20 text-green-400 border border-green-500/40">
								✓ 承認済み
							</span>
						) : (
							<span className="text-[10px] px-2 py-0.5 rounded-full font-medium bg-red-500/20 text-red-400 border border-red-500/40">
								✕ 却下
							</span>
						)}
					</div>
				</div>

				{/* ===== Progress Stepper ===== */}
				<div className="px-4 py-2">
					<div className="flex items-center gap-0.5">
						{allPhaseKeys.map((phaseKey, idx) => {
							const phase = flowPhases.find(p => p.key === phaseKey)
							if (!phase) return null

							const isCurrent = phaseKey === currentFlowKey
							const phaseIdx = allPhaseKeys.indexOf(phaseKey)
							const currentPhaseIdx = allPhaseKeys.indexOf(currentFlowKey)
							const isCompleted = phaseIdx < currentPhaseIdx || (phaseIdx === currentPhaseIdx && status === 'approved')
							const isUpcoming = phaseIdx > currentPhaseIdx

							return (
								<Fragment key={phaseKey}>
									{idx > 0 && (
										<div className={`flex-1 h-[2px] mx-0.5 rounded-full transition-colors ${
											isCompleted ? 'bg-green-500/60' :
											isCurrent && status === 'pending' ? 'bg-[var(--vscode-focusBorder)]/40' :
											'bg-[var(--vscode-widget-border)]/30'
										}`} />
									)}
									<div className="flex flex-col items-center gap-1 min-w-[40px]">
										<div className={`w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold transition-all ${
											isCompleted ? 'bg-green-500/30 text-green-400 border border-green-500/50' :
											isCurrent && status === 'pending' ? 'bg-[var(--vscode-focusBorder)]/30 text-[var(--vscode-focusBorder)] border-2 border-[var(--vscode-focusBorder)] scale-110' :
											isCurrent && status === 'rejected' ? 'bg-red-500/30 text-red-400 border border-red-500/50' :
											'bg-[var(--vscode-widget-border)]/20 text-[var(--vscode-foreground)]/40 border border-[var(--vscode-widget-border)]/30'
										}`}>
											{isCompleted ? '✓' : phase.icon}
										</div>
										<span className={`text-[9px] font-medium leading-none ${
											isCurrent ? 'text-[var(--vscode-foreground)]' :
											isCompleted ? 'text-green-400/80' :
											'text-[var(--vscode-foreground)]/30'
										}`}>
											{phase.label}
										</span>
									</div>
								</Fragment>
							)
						})}
					</div>
				</div>

				{/* ===== Document Preview ===== */}
				<div className="px-4 py-1">
					<button
						onClick={() => setIsExpanded(!isExpanded)}
						className="w-full text-left"
					>
						<div className={`rounded-md border transition-colors ${
							isExpanded
								? 'border-[var(--vscode-focusBorder)]/40 bg-[var(--vscode-editor-background)]'
								: 'border-[var(--vscode-widget-border)]/30 bg-[var(--vscode-editor-background)] hover:border-[var(--vscode-focusBorder)]/30'
						}`}>
							{/* Doc header */}
							<div className="flex items-center justify-between px-3 py-2">
								<div className="flex items-center gap-2">
									<svg className="w-4 h-4 opacity-60" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
										<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
										<polyline points="14 2 14 8 20 8" />
										<line x1="16" y1="13" x2="8" y2="13" />
										<line x1="16" y1="17" x2="8" y2="17" />
									</svg>
									<span className="text-xs font-semibold text-[var(--vscode-foreground)]">
										{chatMessage.mdFileName}
									</span>
								</div>
								<span className="text-[10px] opacity-40">
									{isExpanded ? '▼ 折りたたむ' : '▶ 内容を表示'}
								</span>
							</div>

							{/* Doc content */}
							{isExpanded && (
								<div className="border-t border-[var(--vscode-widget-border)]/20 px-3 py-2 max-h-48 overflow-y-auto">
									<pre className="whitespace-pre-wrap font-mono text-[10px] leading-[1.6] text-[var(--vscode-foreground)]/70">
										{chatMessage.mdContent.length > 2000
											? chatMessage.mdContent.substring(0, 2000) + '\n\n... (truncated)'
											: chatMessage.mdContent}
									</pre>
								</div>
							)}
						</div>
					</button>
				</div>

				{/* ===== Task Progress ===== */}
				<div className="px-4 pt-1 pb-1">
					<div className="flex items-center gap-2">
						<div className="flex-1 h-1.5 rounded-full bg-[var(--vscode-widget-border)]/20 overflow-hidden">
							<div
								className={`h-full rounded-full transition-all duration-500 ${
									status === 'approved' ? 'bg-green-500/70' :
									status === 'rejected' ? 'bg-red-500/70' :
									'bg-[var(--vscode-focusBorder)]/70'
								}`}
								style={{ width: `${((currentIdx + (status === 'approved' ? 1 : 0)) / totalTasks) * 100}%` }}
							/>
						</div>
						<span className="text-[10px] text-[var(--vscode-foreground)]/50 font-mono whitespace-nowrap">
							{currentIdx + (status === 'approved' ? 1 : 0)}/{totalTasks}
						</span>
					</div>
				</div>

				{/* ===== Action Buttons ===== */}
				{status === 'pending' && (
					<div className="px-4 pt-2 pb-3">
						<div className="flex gap-2">
							<button
								onClick={onApprove}
								className="flex-1 px-4 py-2 rounded-md text-sm font-semibold transition-all duration-200 bg-green-600 hover:bg-green-500 active:bg-green-700 text-white shadow-sm hover:shadow-md flex items-center justify-center gap-2"
							>
								承認して次へ進む
								<svg className="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
									<polyline points="9 18 15 12 9 6" />
								</svg>
							</button>
							<button
								onClick={onReject}
								className="px-4 py-2 rounded-md text-sm font-medium transition-all duration-200 border border-[var(--vscode-widget-border)]/50 text-[var(--vscode-foreground)]/70 hover:text-[var(--vscode-foreground)] hover:border-[var(--vscode-widget-border)] hover:bg-[var(--vscode-editor-background)]"
							>
								やり直す
							</button>
						</div>
					</div>
				)}

				{/* ===== Completed Status Message ===== */}
				{status === 'approved' && (
					<div className="px-4 pt-1 pb-3">
						<div className="flex items-center gap-2 text-xs text-green-400/80">
							<svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
								<polyline points="20 6 9 17 4 12" />
							</svg>
							<span>承認済み — 次のタスクを実行中...</span>
						</div>
					</div>
				)}
				{status === 'rejected' && (
					<div className="px-4 pt-1 pb-3">
						<div className="flex items-center gap-2 text-xs text-red-400/80">
							<svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
								<line x1="18" y1="6" x2="6" y2="18" />
								<line x1="6" y1="6" x2="18" y2="18" />
							</svg>
							<span>却下 — オーケストレーションを停止しました</span>
						</div>
					</div>
				)}
			</div>
		</div>
	)
}

const CommandBarInChat = () => {
	const { stateOfURI: commandBarStateOfURI, sortedURIs: sortedCommandBarURIs } = useCommandBarState()
	const numFilesChanged = sortedCommandBarURIs.length

	const accessor = useAccessor()
	const editCodeService = accessor.get('IEditCodeService')
	const commandService = accessor.get('ICommandService')
	const chatThreadsState = useChatThreadsState()
	const commandBarState = useCommandBarState()
	const chatThreadsStreamState = useChatThreadsStreamState(chatThreadsState.currentThreadId)

	// (
	// 	<IconShell1
	// 		Icon={CopyIcon}
	// 		onClick={copyChatToClipboard}
	// 		data-tooltip-id='void-tooltip'
	// 		data-tooltip-place='top'
	// 		data-tooltip-content='Copy chat JSON'
	// 	/>
	// )

	const [fileDetailsOpenedState, setFileDetailsOpenedState] = useState<'auto-opened' | 'auto-closed' | 'user-opened' | 'user-closed'>('auto-closed');
	const isFileDetailsOpened = fileDetailsOpenedState === 'auto-opened' || fileDetailsOpenedState === 'user-opened';


	useEffect(() => {
		// close the file details if there are no files
		// this converts 'user-closed' to 'auto-closed'
		if (numFilesChanged === 0) {
			setFileDetailsOpenedState('auto-closed')
		}
		// open the file details if it hasnt been closed
		if (numFilesChanged > 0 && fileDetailsOpenedState !== 'user-closed') {
			setFileDetailsOpenedState('auto-opened')
		}
	}, [fileDetailsOpenedState, setFileDetailsOpenedState, numFilesChanged])


	const isFinishedMakingThreadChanges = (
		// there are changed files
		commandBarState.sortedURIs.length !== 0
		// none of the files are streaming
		&& commandBarState.sortedURIs.every(uri => !commandBarState.stateOfURI[uri.fsPath]?.isStreaming)
	)

	// ======== status of agent ========
	// This icon answers the question "is the LLM doing work on this thread?"
	// assume it is single threaded for now
	// green = Running
	// orange = Requires action
	// dark = Done

	const threadStatus = (
		chatThreadsStreamState?.isRunning === 'awaiting_user' ? { title: '承認待ち', color: 'yellow', } as const
			: chatThreadsStreamState?.isRunning ? { title: '実行中', color: 'orange', } as const
				: { title: '完了', color: 'dark', } as const
	)


	const threadStatusHTML = <StatusIndicator className='mx-1' indicatorColor={threadStatus.color} title={threadStatus.title} />


	// ======== info about changes ========
	// num files changed
	// acceptall + rejectall
	// popup info about each change (each with num changes + acceptall + rejectall of their own)

	const numFilesChangedStr = numFilesChanged === 0 ? '変更されたファイルはありません'
		: `${sortedCommandBarURIs.length}件の変更されたファイル`




	const acceptRejectAllButtons = <div
		// do this with opacity so that the height remains the same at all times
		className={`flex items-center gap-0.5
			${isFinishedMakingThreadChanges ? '' : 'opacity-0 pointer-events-none'}`
		}
	>
		<IconShell1 // RejectAllButtonWrapper
			// text="Reject All"
			// className="text-xs"
			Icon={X}
			onClick={() => {
				sortedCommandBarURIs.forEach(uri => {
					editCodeService.acceptOrRejectAllDiffAreas({
						uri,
						removeCtrlKs: true,
						behavior: "reject",
						_addToHistory: true,
					});
				});
			}}
			data-tooltip-id='void-tooltip'
			data-tooltip-place='top'
			data-tooltip-content='すべて拒否'
		/>

		<IconShell1 // AcceptAllButtonWrapper
			// text="Accept All"
			// className="text-xs"
			Icon={Check}
			onClick={() => {
				sortedCommandBarURIs.forEach(uri => {
					editCodeService.acceptOrRejectAllDiffAreas({
						uri,
						removeCtrlKs: true,
						behavior: "accept",
						_addToHistory: true,
					});
				});
			}}
			data-tooltip-id='void-tooltip'
			data-tooltip-place='top'
			data-tooltip-content='すべて承認'
		/>



	</div>


	// !select-text cursor-auto
	const fileDetailsContent = <div className="px-2 gap-1 w-full overflow-y-auto">
		{sortedCommandBarURIs.map((uri, i) => {
			const basename = getBasename(uri.fsPath)

			const { sortedDiffIds, isStreaming } = commandBarStateOfURI[uri.fsPath] ?? {}
			const isFinishedMakingFileChanges = !isStreaming

			const numDiffs = sortedDiffIds?.length || 0

			const fileStatus = (isFinishedMakingFileChanges
				? { title: '完了', color: 'dark', } as const
				: { title: '実行中', color: 'orange', } as const
			)

			const fileNameHTML = <div
				className="flex items-center gap-1.5 text-void-fg-3 hover:brightness-125 transition-all duration-200 cursor-pointer"
				onClick={() => voidOpenFileFn(uri, accessor)}
			>
				{/* <FileIcon size={14} className="text-void-fg-3" /> */}
				<span className="text-void-fg-3">{basename}</span>
			</div>




			const detailsContent = <div className='flex px-4'>
				<span className="text-void-fg-3 opacity-80">{numDiffs} diff{numDiffs !== 1 ? 's' : ''}</span>
			</div>

			const acceptRejectButtons = <div
				// do this with opacity so that the height remains the same at all times
				className={`flex items-center gap-0.5
					${isFinishedMakingFileChanges ? '' : 'opacity-0 pointer-events-none'}
				`}
			>
				{/* <JumpToFileButton
					uri={uri}
					data-tooltip-id='void-tooltip'
					data-tooltip-place='top'
					data-tooltip-content='Go to file'
				/> */}
				<IconShell1 // RejectAllButtonWrapper
					Icon={X}
					onClick={() => { editCodeService.acceptOrRejectAllDiffAreas({ uri, removeCtrlKs: true, behavior: "reject", _addToHistory: true, }); }}
					data-tooltip-id='void-tooltip'
					data-tooltip-place='top'
					data-tooltip-content='ファイルを拒否'

				/>
				<IconShell1 // AcceptAllButtonWrapper
					Icon={Check}
					onClick={() => { editCodeService.acceptOrRejectAllDiffAreas({ uri, removeCtrlKs: true, behavior: "accept", _addToHistory: true, }); }}
					data-tooltip-id='void-tooltip'
					data-tooltip-place='top'
					data-tooltip-content='ファイルを承認'
				/>

			</div>

			const fileStatusHTML = <StatusIndicator className='mx-1' indicatorColor={fileStatus.color} title={fileStatus.title} />

			return (
				// name, details
				<div key={i} className="flex justify-between items-center">
					<div className="flex items-center">
						{fileNameHTML}
						{detailsContent}
					</div>
					<div className="flex items-center gap-2">
						{acceptRejectButtons}
						{fileStatusHTML}
					</div>
				</div>
			)
		})}
	</div>

	const fileDetailsButton = (
		<button
			className={`flex items-center gap-1 rounded ${numFilesChanged === 0 ? 'cursor-pointer' : 'cursor-pointer hover:brightness-125 transition-all duration-200'}`}
			onClick={() => isFileDetailsOpened ? setFileDetailsOpenedState('user-closed') : setFileDetailsOpenedState('user-opened')}
			type='button'
			disabled={numFilesChanged === 0}
		>
			<svg
				className="transition-transform duration-200 size-3.5"
				style={{
					transform: isFileDetailsOpened ? 'rotate(0deg)' : 'rotate(180deg)',
					transition: 'transform 0.2s cubic-bezier(0.25, 0.1, 0.25, 1)'
				}}
				xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="18 15 12 9 6 15"></polyline>
			</svg>
			{numFilesChangedStr}
		</button>
	)

	return (
		<>
			{/* file details */}
			<div className='px-2'>
				<div
					className={`
						select-none
						flex w-full rounded-t-lg bg-void-bg-3
						text-void-fg-3 text-xs text-nowrap

						overflow-hidden transition-all duration-200 ease-in-out
						${isFileDetailsOpened ? 'max-h-24' : 'max-h-0'}
					`}
				>
					{fileDetailsContent}
				</div>
			</div>
			{/* main content */}
			<div
				className={`
					select-none
					flex w-full rounded-t-lg bg-void-bg-3
					text-void-fg-3 text-xs text-nowrap
					border-t border-l border-r border-zinc-300/10

					px-2 py-1
					justify-between
				`}
			>
				<div className="flex gap-2 items-center">
					{fileDetailsButton}
				</div>
				<div className="flex gap-2 items-center">
					{acceptRejectAllButtons}
					{threadStatusHTML}
				</div>
			</div>
		</>
	)
}



const EditToolSoFar = ({ toolCallSoFar, }: { toolCallSoFar: RawToolCallObj }) => {

	if (!isABuiltinToolName(toolCallSoFar.name)) return null

	const accessor = useAccessor()

	const uri = toolCallSoFar.rawParams.uri ? URI.file(toolCallSoFar.rawParams.uri) : undefined

	const title = titleOfBuiltinToolName[toolCallSoFar.name].proposed

	const uriDone = toolCallSoFar.doneParams.includes('uri')
	const desc1 = <span className='flex items-center'>
		{uriDone ?
			getBasename(toolCallSoFar.rawParams['uri'] ?? 'unknown')
			: `Generating`}
		<IconLoading />
	</span>

	const desc1OnClick = () => { uri && voidOpenFileFn(uri, accessor) }

	// If URI has not been specified
	return <ToolHeaderWrapper
		title={title}
		desc1={desc1}
		desc1OnClick={desc1OnClick}
	>
		<EditToolChildren
			uri={uri}
			code={toolCallSoFar.rawParams.search_replace_blocks ?? toolCallSoFar.rawParams.new_content ?? ''}
			type={'rewrite'} // as it streams, show in rewrite format, don't make a diff editor
		/>
		<IconLoading />
	</ToolHeaderWrapper>

}


